  "basics#ButtonGroup · Dropdown Menu": "<ButtonGroup>\n  <Button variant=\"outline\">Snooze</Button>\n  <DropdownMenu>\n    <DropdownMenuTrigger\n      render={<Button variant=\"outline\" size=\"icon\" aria-label=\"More Options\"><ChevronRight /></Button>}\n    />\n    <DropdownMenuContent align=\"end\" className=\"w-40\">\n      <DropdownMenuGroup>\n        <DropdownMenuItem>Archive</DropdownMenuItem>\n        <DropdownMenuItem>Report</DropdownMenuItem>\n      </DropdownMenuGroup>\n      <DropdownMenuSeparator />\n      <DropdownMenuGroup>\n        <DropdownMenuItem>\n          <ClockIcon /> Snooze\n        </DropdownMenuItem>\n        <DropdownMenuItem>\n          <PlusIcon /> Add to Calendar\n        </DropdownMenuItem>\n        <DropdownMenuItem>\n          <PlusIcon /> Add to List\n        </DropdownMenuItem>\n      </DropdownMenuGroup>\n    </DropdownMenuContent>\n  </DropdownMenu>\n</ButtonGroup>\n<ButtonGroup>\n  <Button variant=\"outline\">Button</Button>\n  <DropdownMenu>\n    <DropdownMenuTrigger\n      render={<Button variant=\"outline\" size=\"icon\" aria-label=\"More Options\"><ChevronRight /></Button>}\n    />\n    <DropdownMenuContent align=\"end\" className=\"w-40\">\n      <DropdownMenuItem>\n        <ClockIcon /> Snooze\n      </DropdownMenuItem>\n    </DropdownMenuContent>\n  </DropdownMenu>\n</ButtonGroup>",
