  "forms#Input · Field (Field Wrapper)": "<Field>\n  <FieldLabel htmlFor=\"i-field\">Email</FieldLabel>\n  <Input id=\"i-field\" type=\"email\" placeholder=\"you@example.com\" />\n</Field>",
  "forms#Input · Field Group": "<FieldGroup>\n  <Field>\n    <FieldLabel htmlFor=\"i-fg1\">First name</FieldLabel>\n    <Input id=\"i-fg1\" placeholder=\"John\" />\n  </Field>\n  <Field>\n    <FieldLabel htmlFor=\"i-fg2\">Last name</FieldLabel>\n    <Input id=\"i-fg2\" placeholder=\"Doe\" />\n  </Field>\n</FieldGroup>",
  "forms#Input · File": "<Input type=\"file\" />",
  "forms#Input · Grid": "<div className=\"grid w-full grid-cols-2 gap-2\">\n  <Input placeholder=\"First name\" />\n  <Input placeholder=\"Last name\" />\n  <Input placeholder=\"City\" />\n  <Input placeholder=\"ZIP\" />\n</div>",
  "forms#Input · Inline (Prefix)": "<InputGroup>\n  <InputGroupAddon align=\"inline-start\">\n    <InputGroupText>https://</InputGroupText>\n  </InputGroupAddon>\n  <InputGroupInput placeholder=\"example.com\" />\n</InputGroup>",
