  "navigation#ContextMenu · Basic": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for basic actions\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-48\">\n    <ContextMenuGroup>\n      <ContextMenuItem>Copy Link</ContextMenuItem>\n      <ContextMenuItem>Save Image</ContextMenuItem>\n      <ContextMenuItem>Inspect</ContextMenuItem>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Checkboxes": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for toggle options\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-52\">\n    <ContextMenuGroup>\n      <ContextMenuLabel>Layers</ContextMenuLabel>\n      <ContextMenuCheckboxItem checked={ctxBookmarks} onCheckedChange={setCtxBookmarks}>\n        Grid\n      </ContextMenuCheckboxItem>\n      <ContextMenuCheckboxItem checked={ctxUrls} onCheckedChange={setCtxUrls}>\n        Rulers\n      </ContextMenuCheckboxItem>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Composition": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[150px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click here\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-64\">\n    <ContextMenuGroup>\n      <ContextMenuItem inset>\n        Back <ContextMenuShortcut>⌘[</ContextMenuShortcut>\n      </ContextMenuItem>\n      <ContextMenuItem inset disabled>\n        Forward <ContextMenuShortcut>⌘]</ContextMenuShortcut>\n      </ContextMenuItem>\n      <ContextMenuItem inset>\n        Reload <ContextMenuShortcut>⌘R</ContextMenuShortcut>\n      </ContextMenuItem>\n    </ContextMenuGroup>\n    <ContextMenuSub>\n      <ContextMenuSubTrigger inset>More Tools</ContextMenuSubTrigger>\n      <ContextMenuSubContent className=\"w-48\">\n        <ContextMenuGroup>\n          <ContextMenuItem>\n            Save Page As... <ContextMenuShortcut>⇧⌘S</ContextMenuShortcut>\n          </ContextMenuItem>\n          <ContextMenuItem>Create Shortcut...</ContextMenuItem>\n          <ContextMenuItem>Name Window...</ContextMenuItem>\n        </ContextMenuGroup>\n        <ContextMenuSeparator />\n        <ContextMenuGroup>\n          <ContextMenuItem>Developer Tools</ContextMenuItem>\n        </ContextMenuGroup>\n      </ContextMenuSubContent>\n    </ContextMenuSub>\n    <ContextMenuSeparator />\n    <ContextMenuGroup>\n      <ContextMenuCheckboxItem\n        checked={ctxBookmarks}\n        onCheckedChange={setCtxBookmarks}\n      >\n        Show Bookmarks Bar <ContextMenuShortcut>⌘⇧B</ContextMenuShortcut>\n      </ContextMenuCheckboxItem>\n      <ContextMenuCheckboxItem\n        checked={ctxUrls}\n        onCheckedChange={setCtxUrls}\n      >\n        Show Full URLs\n      </ContextMenuCheckboxItem>\n    </ContextMenuGroup>\n    <ContextMenuSeparator />\n    <ContextMenuRadioGroup value={ctxPerson} onValueChange={setCtxPerson}>\n      <ContextMenuLabel inset>People</ContextMenuLabel>\n      <ContextMenuSeparator />\n      <ContextMenuRadioItem value=\"pedro\">Pedro Duarte</ContextMenuRadioItem>\n      <ContextMenuRadioItem value=\"colm\">Colm Tuite</ContextMenuRadioItem>\n    </ContextMenuRadioGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Destructive": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for destructive actions\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-48\">\n    <ContextMenuGroup>\n      <ContextMenuItem>Inspect</ContextMenuItem>\n      <ContextMenuItem>Rename</ContextMenuItem>\n    </ContextMenuGroup>\n    <ContextMenuSeparator />\n    <ContextMenuGroup>\n      <ContextMenuItem variant=\"destructive\">\n        <Trash2 className=\"size-4\" />\n        <span>Delete</span>\n      </ContextMenuItem>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Groups": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for grouped items\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-52\">\n    <ContextMenuGroup>\n      <ContextMenuLabel>Editing</ContextMenuLabel>\n      <ContextMenuItem>Select All</ContextMenuItem>\n      <ContextMenuItem>Invert Selection</ContextMenuItem>\n    </ContextMenuGroup>\n    <ContextMenuSeparator />\n    <ContextMenuGroup>\n      <ContextMenuLabel>View</ContextMenuLabel>\n      <ContextMenuItem>Zoom In</ContextMenuItem>\n      <ContextMenuItem>Zoom Out</ContextMenuItem>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Icons": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for icon options\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-48\">\n    <ContextMenuGroup>\n      <ContextMenuItem>\n        <Copy className=\"size-4\" />\n        <span>Duplicate</span>\n      </ContextMenuItem>\n      <ContextMenuItem>\n        <Download className=\"size-4\" />\n        <span>Download</span>\n      </ContextMenuItem>\n      <ContextMenuItem>\n        <Share2 className=\"size-4\" />\n        <span>Share</span>\n      </ContextMenuItem>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#ContextMenu · Radio": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click to choose alignment\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-48\">\n    <ContextMenuRadioGroup value={ctxPerson} onValueChange={setCtxPerson}>\n      <ContextMenuLabel>Alignment</ContextMenuLabel>\n      <ContextMenuRadioItem value=\"left\">Left</ContextMenuRadioItem>\n      <ContextMenuRadioItem value=\"center\">Center</ContextMenuRadioItem>\n      <ContextMenuRadioItem value=\"right\">Right</ContextMenuRadioItem>\n    </ContextMenuRadioGroup>\n  </ContextMenuContent>\n</ContextMenu>",
