  "navigation#ContextMenu · Submenu": "<ContextMenu>\n  <ContextMenuTrigger className=\"flex h-[120px] w-full items-center justify-center rounded-md border border-dashed text-sm\">\n    Right click for submenus\n  </ContextMenuTrigger>\n  <ContextMenuContent className=\"w-48\">\n    <ContextMenuGroup>\n      <ContextMenuItem>Open</ContextMenuItem>\n      <ContextMenuSub>\n        <ContextMenuSubTrigger>Share</ContextMenuSubTrigger>\n        <ContextMenuSubContent className=\"w-40\">\n          <ContextMenuGroup>\n            <ContextMenuItem>AirDrop</ContextMenuItem>\n            <ContextMenuItem>Messages</ContextMenuItem>\n            <ContextMenuItem>Mail</ContextMenuItem>\n          </ContextMenuGroup>\n        </ContextMenuSubContent>\n      </ContextMenuSub>\n    </ContextMenuGroup>\n  </ContextMenuContent>\n</ContextMenu>",
  "navigation#DropdownMenu · Avatar": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"ghost\" className=\"relative h-8 w-8 rounded-full p-0\" />}>\n    <Avatar className=\"h-8 w-8\">\n      <AvatarImage src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=64&h=64&fit=crop&crop=faces\" alt=\"Avatar\" />\n      <AvatarFallback>SC</AvatarFallback>\n    </Avatar>\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-56\" align=\"end\">\n    <DropdownMenuGroup>\n      <DropdownMenuLabel className=\"font-normal\">\n        <div className=\"flex flex-col space-y-1\">\n          <p className=\"text-sm font-medium leading-none\">shadcn</p>\n          <p className=\"text-xs leading-none text-muted-foreground\">m@example.com</p>\n        </div>\n      </DropdownMenuLabel>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem>\n        <User className=\"size-4\" />\n        <span>Profile</span>\n        <DropdownMenuShortcut>⇧⌘P</DropdownMenuShortcut>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        <CreditCard className=\"size-4\" />\n        <span>Billing</span>\n        <DropdownMenuShortcut>⌘B</DropdownMenuShortcut>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        <Settings className=\"size-4\" />\n        <span>Settings</span>\n        <DropdownMenuShortcut>⌘S</DropdownMenuShortcut>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem variant=\"destructive\">\n        <LogOut className=\"size-4\" />\n        <span>Log out</span>\n        <DropdownMenuShortcut>⇧⌘Q</DropdownMenuShortcut>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
  "navigation#DropdownMenu · Basic": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>\n    Actions\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-48\">\n    <DropdownMenuGroup>\n      <DropdownMenuItem>Edit</DropdownMenuItem>\n      <DropdownMenuItem>Duplicate</DropdownMenuItem>\n      <DropdownMenuItem>Archive</DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
  "navigation#DropdownMenu · Checkboxes": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>\n    Appearance\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-56\">\n    <DropdownMenuGroup>\n      <DropdownMenuLabel>View Options</DropdownMenuLabel>\n      <DropdownMenuCheckboxItem\n        checked={showStatusBar}\n        onCheckedChange={setShowStatusBar}\n      >\n        Status Bar\n      </DropdownMenuCheckboxItem>\n      <DropdownMenuCheckboxItem\n        checked={showActivityBar}\n        onCheckedChange={setShowActivityBar}\n      >\n        Activity Bar\n      </DropdownMenuCheckboxItem>\n      <DropdownMenuCheckboxItem\n        checked={showPanel}\n        onCheckedChange={setShowPanel}\n      >\n        Panel\n      </DropdownMenuCheckboxItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
