  "navigation#DropdownMenu · Composition": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>\n    Open Menu\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-56\">\n    <DropdownMenuGroup>\n      <DropdownMenuLabel>My Account</DropdownMenuLabel>\n      <DropdownMenuItem>\n        Profile <DropdownMenuShortcut>⇧⌘P</DropdownMenuShortcut>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        Billing <DropdownMenuShortcut>⌘B</DropdownMenuShortcut>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        Settings <DropdownMenuShortcut>⌘S</DropdownMenuShortcut>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        Keyboard shortcuts <DropdownMenuShortcut>⌘K</DropdownMenuShortcut>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem>Team</DropdownMenuItem>\n      <DropdownMenuSub>\n        <DropdownMenuSubTrigger>Invite users</DropdownMenuSubTrigger>\n        <DropdownMenuSubContent>\n          <DropdownMenuGroup>\n            <DropdownMenuItem>Email</DropdownMenuItem>\n            <DropdownMenuItem>Message</DropdownMenuItem>\n            <DropdownMenuSeparator />\n            <DropdownMenuItem>More...</DropdownMenuItem>\n          </DropdownMenuGroup>\n        </DropdownMenuSubContent>\n      </DropdownMenuSub>\n      <DropdownMenuItem>\n        New Team <DropdownMenuShortcut>⌘+T</DropdownMenuShortcut>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem>GitHub</DropdownMenuItem>\n      <DropdownMenuItem>Support</DropdownMenuItem>\n      <DropdownMenuItem disabled>API</DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem variant=\"destructive\">\n        Log out <DropdownMenuShortcut>⇧⌘Q</DropdownMenuShortcut>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
  "navigation#DropdownMenu · Destructive": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>\n    Danger Zone\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-48\">\n    <DropdownMenuGroup>\n      <DropdownMenuItem>Archive Item</DropdownMenuItem>\n      <DropdownMenuItem>Transfer Ownership</DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem variant=\"destructive\">\n        <Trash2 className=\"size-4\" />\n        <span>Delete Project</span>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
  "navigation#DropdownMenu · Icons": "<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>\n    Account\n  </DropdownMenuTrigger>\n  <DropdownMenuContent className=\"w-48\">\n    <DropdownMenuGroup>\n      <DropdownMenuItem>\n        <User className=\"size-4\" />\n        <span>Profile</span>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        <CreditCard className=\"size-4\" />\n        <span>Billing</span>\n      </DropdownMenuItem>\n      <DropdownMenuItem>\n        <Settings className=\"size-4\" />\n        <span>Settings</span>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem variant=\"destructive\">\n        <LogOut className=\"size-4\" />\n        <span>Log out</span>\n      </DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>",
